const CHAT_CODE_BLOCK_PREFIX='\uE010C';
const CHAT_CODE_BLOCK_SUFFIX='\uE010';
const CHAT_INLINE_CODE_PREFIX='\uE011I';
const CHAT_INLINE_CODE_SUFFIX='\uE011';
const CHAT_HISTORY_PAGE_SIZE=80;
function isChatNearBottom(){const box=document.getElementById('messages');if(!box)return true;return box.scrollHeight-box.scrollTop-box.clientHeight<80}
function updateChatJumpLatestButton(){const box=document.getElementById('messages');const button=document.getElementById('chatJumpLatestBtn');if(!box||!button)return;button.hidden=isChatNearBottom()||box.scrollHeight<=box.clientHeight+2}
function bindChatJumpLatestButton(){const box=document.getElementById('messages');const button=document.getElementById('chatJumpLatestBtn');if(box&&!box.dataset.jumpLatestBound){box.dataset.jumpLatestBound='true';box.addEventListener('scroll',updateChatJumpLatestButton,{passive:true})}if(button&&!button.dataset.bound){button.dataset.bound='true';button.onclick=()=>scrollChatToBottom({force:true})}updateChatJumpLatestButton()}
function scrollChatToBottom(options:WebuiChatScrollOptions={}){const box=document.getElementById('messages');if(!box)return;if(!options.force&&!isChatNearBottom())return;requestAnimationFrame(()=>{box.scrollTop=box.scrollHeight;updateChatJumpLatestButton();requestAnimationFrame(()=>{box.scrollTop=box.scrollHeight;updateChatJumpLatestButton()})})}
function markChatRendered(){state.chatRenderVersion=(state.chatRenderVersion||0)+1}
function appendMessage(cls,text,options:WebuiAppendMessageOptions={}){const box=document.getElementById('messages');const stick=options.forceScroll||isChatNearBottom();const previousTop=box?.scrollTop??0;const div=document.createElement('div');div.className='message '+cls;if(options.messageId)div.dataset.messageId=String(options.messageId);if(options.correlationId)div.dataset.correlationId=String(options.correlationId);if(options.peerId)div.dataset.peerId=String(options.peerId);if(options.agentId)div.dataset.agentId=String(options.agentId);if(options.threadId)div.dataset.threadId=String(options.threadId);if(options.contextKey)div.dataset.contextKey=String(options.contextKey);div.insertAdjacentHTML('beforeend',chatMessageActionsHtml());const body=document.createElement('div');body.className='message-body';div.appendChild(body);if(options.meta)div.__meta=options.meta;if(options.attachments)div.__attachments=options.attachments;setMessageText(div,text,options.meta,undefined,undefined,options.attachments);box.appendChild(div);if(stick)scrollChatToBottom({force:true});else box.scrollTop=previousTop;updateChatJumpLatestButton();return div}
function messageBody(div){let body=div.querySelector?.('.message-body');if(!body){body=document.createElement('div');body.className='message-body';div.textContent='';div.appendChild(body)}return body}
function setMessageText(div,text,meta:unknown[]|undefined=undefined,actions:WebuiRecord[]|undefined=undefined,actionResolution:WebuiRecord|null|undefined=undefined,attachments:WebuiChatAttachment[]|undefined=undefined){div.__rawText=String(text??'');if(meta!==undefined)div.__meta=Array.isArray(meta)?meta:[];if(attachments!==undefined)div.__attachments=Array.isArray(attachments)?attachments:[];if(actions!==undefined)div.__actions=Array.isArray(actions)?actions:[];if(actionResolution!==undefined)div.__actionResolution=actionResolution||null;const body=messageBody(div);body.innerHTML=renderChatMarkdown(div.__rawText)+chatMessageMetaHtml(div.__meta)+chatMessageAttachmentsHtml(div.__attachments,div.dataset.messageId)+chatMessageActionResolutionHtml(div.__actionResolution)+chatMessageCustomActionsHtml(div.__actions);bindChatCopyButtons(body);hydrateChatAttachments(body);bindChatMessageActionButtons(div);markChatRendered();return div}
function appendQueuedMessage(id,correlationId){const peerId=currentChatPeerId();const div=appendMessage('system','Queued prompt '+id);const body=messageBody(div);const actions=document.createElement('small');actions.className='queued-message-actions';if(correlationId)actions.insertAdjacentHTML('beforeend',uiTraceControls(correlationId));safe(()=>loadQueue({silent:true}));const btn=document.createElement('button');btn.type='button';btn.textContent='Cancel queued message';btn.className='danger mini-button';btn.onclick=()=>safe(async()=>{await queueActionRequest(peerId,'cancel',id);await loadQueue({silent:true});setMessageText(div,'Cancelled queued prompt '+id)});actions.appendChild(btn);body.appendChild(document.createElement('br'));body.appendChild(actions);bindUiCopyButtons(body);bindUiTraceButtons(body)}
function chatMessageRoleClass(role){return String(role||'system').replace(/[^a-z0-9_-]/gi,'')||'system'}
function isChatUserPromptMessage(message){return message?.role==='user'||(message?.role==='system'&&message?.source==='cli'&&/^Working on\b/i.test(String(message?.text||'')))}
function chatMessageClass(message){return ['message',chatMessageRoleClass(message?.role),isChatUserPromptMessage(message)?'user-prompt':''].filter(Boolean).join(' ')}
function chatMessageMetaHtml(meta){const items=(Array.isArray(meta)?meta:[]).map(item=>String(item||'').trim()).filter(Boolean);return items.length?'<div class="message-meta">'+items.map(item=>'<span>'+esc(item)+'</span>').join('')+'</div>':''}
function chatMessageAttachmentsHtml(attachments:WebuiChatAttachment[]|undefined,messageId:string|undefined=''){const items=(Array.isArray(attachments)?attachments:[]).filter(item=>item&&item.id&&item.name);if(!items.length)return'';return '<div class="chat-attachments">'+items.map(item=>{const id=String(item.id||'');const name=String(item.name||id);const kind=String(item.kind||'file');const mime=String(item.mimeType||'application/octet-stream');const size=Number(item.sizeBytes||0);const isImage=kind==='image'||mime.startsWith('image/');const disabled=!messageId?' disabled aria-disabled="true"':'';const attrs=' data-message-id="'+attr(messageId||'')+'" data-attachment-id="'+attr(id)+'" data-attachment-kind="'+attr(kind)+'" title="'+attr(name)+'"';if(isImage)return '<button type="button" class="chat-attachment chat-attachment-image"'+attrs+disabled+'><span class="chat-attachment-preview">Loading image...</span><small>'+esc(name)+' · '+esc(fmtBytes(size))+'</small></button>';return '<button type="button" class="chat-attachment chat-attachment-file"'+attrs+disabled+'><span>'+esc(chatAttachmentKindLabel(kind,mime))+'</span><small>'+esc(name)+' · '+esc(fmtBytes(size))+'</small></button>'}).join('')+'</div>'}
function chatAttachmentKindLabel(kind,mime){if(kind==='audio'||String(mime||'').startsWith('audio/'))return'Audio';if(kind==='image'||String(mime||'').startsWith('image/'))return'Image';return'File'}
function chatAttachmentDataUrl(file){return 'data:'+(file.mimeType||'application/octet-stream')+';base64,'+(file.dataBase64||'')}
async function fetchChatAttachment(button){return api('/api/chat/attachment',activeChatTabApiOptions({query:{messageId:button.dataset.messageId,attachmentId:button.dataset.attachmentId}}))}
async function loadChatAttachmentPreview(button){if(button.dataset.loaded||button.dataset.loading||button.disabled)return;button.dataset.loading='true';try{const file=await fetchChatAttachment(button);button.dataset.loaded='true';if(String(file.mimeType||'').startsWith('image/')){const preview=button.querySelector('.chat-attachment-preview');if(preview)preview.innerHTML='<img src="'+attr(chatAttachmentDataUrl(file))+'" alt="'+attr(file.name||'Attachment')+'">'}button.onclick=event=>safe(async()=>{event.preventDefault();event.stopPropagation();const data=await fetchChatAttachment(button);downloadBase64(data.name||'attachment',data.dataBase64||'',data.mimeType||'application/octet-stream')},event)}catch(error){button.dataset.loaded='error';button.classList.add('failed');const preview=button.querySelector('.chat-attachment-preview');if(preview)preview.textContent='Preview unavailable';button.title=error instanceof Error?error.message:String(error)}finally{delete button.dataset.loading}}
function hydrateChatAttachments(root:Document|Element=document){root.querySelectorAll?.('.chat-attachment[data-message-id][data-attachment-id]').forEach(button=>{if(!button.dataset.messageId||button.dataset.bound)return;button.dataset.bound='true';button.onclick=event=>safe(async()=>{event.preventDefault();event.stopPropagation();const data=await fetchChatAttachment(button);downloadBase64(data.name||'attachment',data.dataBase64||'',data.mimeType||'application/octet-stream')},event);if(button.classList.contains('chat-attachment-image'))void loadChatAttachmentPreview(button)})}
function chatLoadOlderHtml(){const pagination=state.chatHistoryPagination;if(!pagination?.hasNext||!pagination.nextCursor)return'';return '<div class="chat-history-pager"><button type="button" id="loadOlderChatBtn" class="secondary mini-button" '+(state.chatHistoryLoadingOlder?'disabled':'')+'>'+(state.chatHistoryLoadingOlder?'Loading older...':'Load older messages')+'</button><small>'+esc((state.chatMessages||[]).length+' of '+pagination.total+' shown')+'</small></div>'}
function promptHistoryMessageText(message){return String(messageRawText(message)||'').replace(/^Working on\s+/i,'').trim()}
function promptHistoryMessageMeta(message){return String(message.querySelector?.('small')?.textContent||'').trim()}
function promptHistoryMessageKey(message,index){const key=message.dataset.messageId?'id:'+message.dataset.messageId:message.dataset.correlationId?'correlation:'+message.dataset.correlationId:message.dataset.messageIndex?'index:'+message.dataset.messageIndex:'dom:'+index;message.dataset.promptHistoryKey=key;return key}
function promptHistoryEntries(){const messages=Array.from(document.querySelectorAll('#messages .message.user-prompt'));return messages.map((message,index)=>({message,key:promptHistoryMessageKey(message,index),text:promptHistoryMessageText(message),meta:promptHistoryMessageMeta(message)})).filter(entry=>entry.text).slice(-25).reverse()}
function scrollChatToHistoryPrompt(key){const box=document.getElementById('messages') as HTMLElement|null;const target=box?.querySelector('.message[data-prompt-history-key="'+cssEscape(String(key||''))+'"]') as HTMLElement|null;if(!box||!target){toast('Prompt is not loaded in the current chat page');return}const top=Math.max(0,target.offsetTop-box.offsetTop-Math.max(16,(box.clientHeight-target.clientHeight)/2));box.scrollTo({top,behavior:'smooth'});target.classList.add('message-highlight');setTimeout(()=>target.classList.remove('message-highlight'),1600);updateChatJumpLatestButton()}
function bindPromptHistorySidebar(root=document.getElementById('promptHistoryStream')){if(!root||root.dataset.bound)return;root.dataset.bound='true';root.addEventListener('click',event=>{const button=(event.target as Element|null)?.closest?.('[data-prompt-history-key]') as HTMLElement|null;if(!button)return;event.preventDefault();scrollChatToHistoryPrompt(button.dataset.promptHistoryKey)})}
function renderPromptHistorySidebar(){const root=document.getElementById('promptHistoryStream');if(!root)return;bindPromptHistorySidebar(root);const entries=promptHistoryEntries();root.innerHTML=entries.length?entries.map(entry=>'<button type="button" class="prompt-history-item" data-prompt-history-key="'+attr(entry.key)+'" title="'+attr(entry.text)+'"><span>'+esc(short(entry.text,180))+'</span>'+(entry.meta?'<small>'+esc(entry.meta)+'</small>':'')+'</button>').join(''):'<div class="tool empty">No prompts loaded for this session yet.</div>'}
let promptHistoryRenderFrame=0;
function schedulePromptHistorySidebarRender(){if(state.chatSidebarMode!=='history')return;if(promptHistoryRenderFrame)cancelAnimationFrame(promptHistoryRenderFrame);promptHistoryRenderFrame=requestAnimationFrame(()=>{promptHistoryRenderFrame=0;renderPromptHistorySidebar()})}
const promptHistoryMessagesEl=document.getElementById('messages');
if(promptHistoryMessagesEl)new MutationObserver(schedulePromptHistorySidebarRender).observe(promptHistoryMessagesEl,{childList:true});
function uniqueChatMessages(messages:WebuiChatMessage[]){const byId=new Map<string,WebuiChatMessage>();const withoutId:WebuiChatMessage[]=[];for(const message of messages||[]){const id=String(message?.id||'');if(id)byId.set(id,message);else withoutId.push(message)}return [...withoutId,...byId.values()].sort((left,right)=>Date.parse(left.timestamp)-Date.parse(right.timestamp))}
function chatMessageCorrelation(message){return String(message?.correlationId||'')}
function serverChatHasCorrelation(messages:WebuiChatMessage[],correlationId:string){return Boolean(correlationId&&messages.some(message=>chatMessageCorrelation(message)===correlationId))}
function pruneOptimisticChatMessages(messages:WebuiChatMessage[]){const now=Date.now();state.chatOptimisticMessages=(state.chatOptimisticMessages||[]).filter(message=>{const created=Date.parse(String(message.timestamp||''));if(Number.isFinite(created)&&now-created>300000)return false;const correlationId=chatMessageCorrelation(message);return !serverChatHasCorrelation(messages,correlationId)})}
function currentStreamingChatMessage(messages:WebuiChatMessage[]){if(!currentAgentMessage||!currentAgentMessage.isConnected||!chatElementMatchesCurrentChat(currentAgentMessage))return null;const text=String(currentAgentMessage.__rawText||'');if(!text)return null;const correlationId=String(currentAgentMessage.dataset?.correlationId||'');if(serverChatHasCorrelation(messages,correlationId))return null;return{id:'streaming-'+(correlationId||'agent'),role:'agent',source:'web',timestamp:new Date().toISOString(),text,correlationId,threadId:currentAgentMessage.dataset?.threadId}}
function mergeOptimisticChatMessages(messages:WebuiChatMessage[]){const base=messages||[];pruneOptimisticChatMessages(base);const merged=[...base];for(const message of state.chatOptimisticMessages||[]){const correlationId=chatMessageCorrelation(message);if(!serverChatHasCorrelation(merged,correlationId))merged.push(message)}const streaming=currentStreamingChatMessage(merged);if(streaming)merged.push(streaming);return uniqueChatMessages(merged)}
function upsertOptimisticChatMessage(message:WebuiChatMessage){const correlationId=chatMessageCorrelation(message);if(!correlationId)return;const list=state.chatOptimisticMessages||[];const existing=list.findIndex(item=>chatMessageCorrelation(item)===correlationId);if(existing>=0)list[existing]={...list[existing],...message};else list.push(message);state.chatOptimisticMessages=list}
function removeOptimisticChatMessage(correlationId:string){const id=String(correlationId||'');if(!id)return;state.chatOptimisticMessages=(state.chatOptimisticMessages||[]).filter(message=>chatMessageCorrelation(message)!==id)}
function removeChatMessageForCorrelation(correlationId:string){const id=String(correlationId||'');if(!id)return;removeOptimisticChatMessage(id);document.querySelectorAll('.message[data-correlation-id="'+cssEscape(id)+'"]').forEach(el=>el.remove());state.chatMessages=(state.chatMessages||[]).filter(message=>chatMessageCorrelation(message)!==id);markChatRendered();updateChatJumpLatestButton()}
function renderChatMessages(messages:WebuiChatMessage[]=[],options:WebuiRenderChatOptions={}){const renderMessages=mergeOptimisticChatMessages(messages||[]);state.chatMessages=renderMessages;const box=document.getElementById('messages');if(!box)return;const stick=options.forceScroll||isChatNearBottom();const previousTop=box.scrollTop;const previousHeight=box.scrollHeight;box.innerHTML=chatLoadOlderHtml()+renderMessages.map((m,index)=>'<div class="'+attr(chatMessageClass(m))+'" data-message-index="'+index+'" data-message-id="'+attr(m.id||'')+'" data-correlation-id="'+attr(m.correlationId||'')+'" data-thread-id="'+attr(m.threadId||'')+'">'+chatMessageActionsHtml()+'<small>'+esc((m.source||'web')+' / '+fmtDate(m.timestamp))+'</small><br><div class="message-body">'+renderChatMarkdown(m.text)+chatMessageMetaHtml(m.meta)+chatMessageAttachmentsHtml(m.attachments,m.id)+chatMessageActionResolutionHtml(m.actionResolution)+chatMessageCustomActionsHtml(m.actions)+'</div></div>').join('')+chatWorkingIndicatorHtml();renderMessages.forEach((m,index)=>{const el=box.querySelector<HTMLElement>('.message[data-message-index="'+index+'"]');if(el){el.__rawText=String(m.text??'');el.__meta=Array.isArray(m.meta)?m.meta:[];el.__attachments=Array.isArray(m.attachments)?m.attachments:[];el.__actions=Array.isArray(m.actions)?m.actions:[];el.__actionResolution=m.actionResolution||null}});const older=document.getElementById('loadOlderChatBtn');if(older)older.onclick=()=>safe(loadOlderChatHistory);bindChatCopyButtons(box);hydrateChatAttachments(box);markChatRendered();updateComposerAbortVisibility();syncChatWorkingTimer();bindChatJumpLatestButton();if(options.preserveScrollOffset)box.scrollTop=previousTop+(box.scrollHeight-previousHeight);else if(stick)scrollChatToBottom({force:true});else box.scrollTop=previousTop;updateChatJumpLatestButton()}
Object.assign(window,{renderChatMessages});
async function loadChatHistory(options:WebuiLoadChatHistoryOptions={}){const requestId=(state.chatHistoryRequestId||0)+1;state.chatHistoryRequestId=requestId;const renderVersion=state.chatRenderVersion||0;const data=await api('/api/chat/history',activeChatTabApiOptions({query:{limit:CHAT_HISTORY_PAGE_SIZE}}));if(requestId!==state.chatHistoryRequestId)return false;if(options.skipIfRendered!==false&&(state.chatRenderVersion||0)!==renderVersion)return false;state.chatHistoryPagination=data.pagination||null;renderChatMessages(data.messages||[],options);return true}
async function loadOlderChatHistory(){const pagination=state.chatHistoryPagination;if(!pagination?.hasNext||!pagination.nextCursor||state.chatHistoryLoadingOlder)return;state.chatHistoryLoadingOlder=true;renderChatMessages(state.chatMessages||[],{preserveScrollOffset:true});try{const data=await api('/api/chat/history',activeChatTabApiOptions({query:{limit:CHAT_HISTORY_PAGE_SIZE,cursor:pagination.nextCursor}}));state.chatHistoryPagination=data.pagination||null;renderChatMessages(uniqueChatMessages([...(data.messages||[]),...(state.chatMessages||[])]),{preserveScrollOffset:true})}finally{state.chatHistoryLoadingOlder=false;renderChatMessages(state.chatMessages||[],{preserveScrollOffset:true})}}
let currentAgentMessage=null;
function applyChatHistoryEvent(event:MessageEvent){safe(async()=>{let data:WebuiRecord|null=null;try{data=JSON.parse(event.data||'{}')}catch{}if(!chatEventMatchesCurrentChat(data)){renderChatTabs();return}const messages=Array.isArray(data?.messages)?data.messages as WebuiChatMessage[]:null;if(messages){state.chatHistoryPagination=null;currentAgentMessage=null;renderChatMessages(messages);renderChatTabs();return}await loadChatHistory({skipIfRendered:false});renderChatTabs()})}
function activeSessionPeerId(item){return String(item?.peerId||'local')}
function activeChatTabIdentity(){const tab=state.currentPage==='chat'?activeChatTab():null;if(!tab?.threadId)return null;return{peerId:String(tab.peerId||'local'),agentId:String(tab.agentId||''),threadId:String(tab.threadId||'')}}
function currentChatPeerId(){return activeChatTabIdentity()?.peerId||String(state.selectedPeer||'local')}
function currentChatIdentity(){const tabIdentity=activeChatTabIdentity();if(tabIdentity)return tabIdentity;const session=state.snapshot?.session||{};return{peerId:String(state.selectedPeer||'local'),agentId:String(session.agentId||''),threadId:String(session.threadId||'')}}
function chatEventThreadId(data){const direct=String(data?.threadId||'').trim();if(direct)return direct;const messages=Array.isArray(data?.messages)?data.messages:[];const ids=[...new Set(messages.map(message=>String(message?.threadId||'').trim()).filter(Boolean))];return ids.length===1?ids[0]:''}
function chatEventIdentity(data){const threadId=chatEventThreadId(data);if(!threadId)return null;return{peerId:String(state.eventsTarget||'local'),agentId:String(data?.agentId||''),threadId}}
function chatIdentityMatchesCurrentChat(identity){if(!identity?.threadId)return true;const current=currentChatIdentity();if(!current.threadId)return true;if(identity.peerId!==current.peerId)return false;if(identity.threadId!==current.threadId)return false;return !identity.agentId||!current.agentId||identity.agentId===current.agentId}
function chatEventMatchesCurrentChat(data){return chatIdentityMatchesCurrentChat(chatEventIdentity(data))}
function chatElementMatchesCurrentChat(el){const threadId=String(el?.dataset?.threadId||'').trim();if(!threadId)return true;return chatIdentityMatchesCurrentChat({peerId:String(el.dataset.peerId||state.eventsTarget||'local'),agentId:String(el.dataset.agentId||''),threadId})}
function chatEventAppendOptions(data){const identity=chatEventIdentity(data)||currentChatIdentity();return{peerId:String(identity.peerId||'local'),agentId:String(data?.agentId||identity.agentId||''),threadId:String(identity.threadId||''),contextKey:String(data?.contextKey||'')}}
function handleForeignChatEvent(){renderChatWorkingIndicator();renderSessionControls();renderChatTabs()}
function activeSessionMatchesCurrentChat(item,identity){return activeSessionPeerId(item)===identity.peerId&&String(item.threadId||'')===String(identity.threadId||'')&&(!identity.agentId||!item.agentId||String(item.agentId)===String(identity.agentId))&&(item.status==='running'||item.status==='external'||Boolean(item.approvalRequired))}
function activeSessionsFreshForCurrentChat(peerId){const loaded=state.activeSessionsLoadedTarget||'';if(!state.activeSessionsLastLoadAt)return false;if(loaded==='chat-tabs')return true;if(peerId==='local')return loaded==='local';return loaded===peerId}
function localTurnIsStaleWithoutActive(identity){if(state.localTurnPeerId&&state.localTurnPeerId!==identity.peerId)return true;const started=Date.parse(state.localTurnStartedAt||'');if(!Number.isFinite(started))return false;if(!activeSessionsFreshForCurrentChat(identity.peerId))return false;return state.activeSessionsLastLoadAt>started+1500}
function currentChatWorkingSession(){const identity=currentChatIdentity();if(!identity.threadId)return null;const active=(state.activeSessions?.sessions||[]).find(item=>activeSessionMatchesCurrentChat(item,identity));if(active)return active;if(state.localTurnThreadId===identity.threadId&&(!identity.agentId||!state.localTurnAgentId||state.localTurnAgentId===identity.agentId)){if(localTurnIsStaleWithoutActive(identity)){state.localTurnThreadId=null;state.localTurnAgentId=null;state.localTurnPeerId=null;state.localTurnStartedAt=null;return null}return{source:'web',status:'running',startedAt:state.localTurnStartedAt||new Date().toISOString(),peerId:identity.peerId,agentId:identity.agentId,threadId:identity.threadId}}return null}
function markChatVisibleCompletion(data:WebuiRecord={}){const identity=currentChatIdentity();if(!identity.threadId)return;state.chatVisibleCompletion={...identity,turnId:String(data.id||''),correlationId:String(data.correlationId||''),at:Number.isFinite(Date.parse(String(data.at||'')))?Date.parse(String(data.at)):Date.now()}}
function clearChatVisibleCompletionForCurrentSession(){const identity=currentChatIdentity();const completion=state.chatVisibleCompletion;if(completion&&completion.peerId===identity.peerId&&completion.threadId===identity.threadId&&(!completion.agentId||!identity.agentId||completion.agentId===identity.agentId))state.chatVisibleCompletion=null}
function chatVisibleCompletionMatches(active){const completion=state.chatVisibleCompletion;if(!completion||!active)return false;const completedAt=Number(completion.at||0);if(Date.now()-completedAt>30000){state.chatVisibleCompletion=null;return false}const identity=currentChatIdentity();if(completion.peerId!==identity.peerId||completion.threadId!==identity.threadId)return false;if(completion.agentId&&identity.agentId&&completion.agentId!==identity.agentId)return false;if(!completion.turnId||String(active.id||'')!==completion.turnId)return false;if(active.approvalRequired)return false;const tool=String(active.currentTool||'');if(tool&&tool!=='-')return false;const updated=Date.parse(active.updatedAt||'');if(Number.isFinite(updated)&&updated>completedAt+1000)return false;const activeStarted=Date.parse(active.startedAt||'');if(Number.isFinite(activeStarted)&&activeStarted>completedAt+1000)return false;return true}
function currentChatWorkingIndicatorSession(){const active=currentChatWorkingSession();return chatVisibleCompletionMatches(active)?null:active}
function currentCompletionSoundSessionKey(){const identity=currentChatIdentity();if(!identity.threadId)return'';return [identity.peerId,identity.agentId||'',identity.threadId].join('::')}
function syncCompletionSoundActivity(){const key=currentCompletionSoundSessionKey();const active=Boolean(currentChatWorkingSession());if(!key){state.completionSoundArmedKey=null;return}if(active){state.completionSoundArmedKey=key;return}if(state.completionSoundArmedKey===key){state.completionSoundArmedKey=null;playCompletionSound();return}if(state.completionSoundArmedKey&&state.completionSoundArmedKey!==key)state.completionSoundArmedKey=null}
function clearCurrentChatWorkingState(){state.localTurnThreadId=null;state.localTurnAgentId=null;state.localTurnPeerId=null;state.localTurnStartedAt=null;const identity=currentChatIdentity();if(!identity.threadId||!state.activeSessions?.sessions)return;state.activeSessions={...state.activeSessions,sessions:state.activeSessions.sessions.filter(item=>!activeSessionMatchesCurrentChat(item,identity))};updateActiveSessionsCount(state.activeSessions.sessions)}
function updateComposerAbortVisibility(){const active=Boolean(currentChatWorkingSession());const form=document.getElementById('promptForm');const button=document.getElementById('abortBtn') as HTMLButtonElement|null;if(button)button.hidden=!active;if(form)form.classList.toggle('composer-abort-visible',active)}
function chatWorkingStartedMs(active){const parsed=Date.parse(active?.startedAt||'');if(Number.isFinite(parsed))return parsed;if(Number.isFinite(Number(active?.durationMs)))return Date.now()-Number(active.durationMs);return Date.now()}
function fmtChatWorkingElapsed(ms){const sec=Math.max(0,Math.floor(ms/1000));if(sec<60)return sec+'s';const min=Math.floor(sec/60);if(min<60)return min+'m '+(sec%60)+'s';const hours=Math.floor(min/60);return hours+'h '+(min%60)+'m'}
function updateChatWorkingElapsed(){const el=document.getElementById('chatWorkingElapsed');if(!el)return;const started=Number(el.dataset.workingStartedMs||0);if(!Number.isFinite(started)||started<=0)return;el.textContent='('+fmtChatWorkingElapsed(Date.now()-started)+')'}
function stopChatWorkingTimer(){if(state.chatWorkingTimer)clearInterval(state.chatWorkingTimer);state.chatWorkingTimer=null}
function syncChatWorkingTimer(){updateChatWorkingElapsed();if(!document.getElementById('chatWorkingIndicator')){stopChatWorkingTimer();return}if(state.chatWorkingTimer)return;state.chatWorkingTimer=setInterval(()=>{if(!document.getElementById('chatWorkingIndicator')){stopChatWorkingTimer();return}updateChatWorkingElapsed()},1000)}
function chatWorkingIndicatorHtml(){const active=currentChatWorkingIndicatorSession();if(!active)return'';const approval=(active.approvalRequired||null) as WebuiRecord|null;const source=activeSourceLabel(active.source);const tool=active.currentTool||active.lastTool;const detail=approval?['Action required',approval.command||approval.toolName||''].filter(Boolean).join(' · '):[source,tool&&tool!=='-'?'tool '+tool:'',active.queueLength?active.queueLength+' queued':''].filter(Boolean).join(' · ');const startedMs=chatWorkingStartedMs(active);const label=approval?'Action required':'Working...';return '<div id="chatWorkingIndicator" class="chat-working-indicator '+(approval?'action-required':'')+'" aria-live="polite"><span class="chat-working-dot"></span><span>'+esc(label)+' <span id="chatWorkingElapsed" data-working-started-ms="'+attr(String(startedMs))+'">('+esc(fmtChatWorkingElapsed(Date.now()-startedMs))+')</span></span>'+(detail?'<small>'+esc(detail)+'</small>':'')+'</div>'}
