function renderChatMarkdown(text){let output=esc(String(text??''));const codeBlocks=[];const inlineCode=[];output=extractChatCodeBlocks(output,codeBlocks);output=extractChatInlineCode(output,inlineCode);output=formatChatBold(output);output=formatChatItalic(output);output=formatChatLinks(output);output=formatChatBlockquotes(output);output=formatChatLists(output);output=formatChatHeadings(output);output=restoreChatMarkdown(output,CHAT_INLINE_CODE_PREFIX,CHAT_INLINE_CODE_SUFFIX,inlineCode);output=restoreChatMarkdown(output,CHAT_CODE_BLOCK_PREFIX,CHAT_CODE_BLOCK_SUFFIX,codeBlocks);return normalizeChatCodeBlockSpacing(output)}
function extractChatCodeBlocks(text,blocks){return text.replace(/```([^\n`]*)\n?([\s\S]*?)```/g,(_match,rawLanguage,rawCode)=>{const language=String(rawLanguage||'').trim().replace(/[^a-zA-Z0-9_+-]/g,'');const className=language?' class="language-'+attr(language)+'"':'';const label=language?' data-code-language="'+attr(language)+'"':'';const code=String(rawCode??'').replace(/\n$/,'');const block='<pre class="chat-code-block" tabindex="0" title="Copy code" data-chat-copy="code-block"'+label+'><code'+className+'>'+code+'</code></pre>';const index=blocks.push(block)-1;return CHAT_CODE_BLOCK_PREFIX+index+CHAT_CODE_BLOCK_SUFFIX})}
function normalizeChatCodeBlockSpacing(text){return text.replace(/(<\/pre>)[ \t]*\n(?:[ \t]*\n)+/g,'$1\n')}
function extractChatInlineCode(text,inline){let result='';let index=0;while(index<text.length){if(text[index]!=='`'){result+=text[index];index+=1;continue}let tickCount=1;while(text[index+tickCount]==='`')tickCount+=1;const fence='`'.repeat(tickCount);const start=index+tickCount;const end=text.indexOf(fence,start);if(end===-1){result+=fence;index+=tickCount;continue}const content=text.slice(start,end);if(content.includes('\n')){result+=fence;index+=tickCount;continue}const button='<button type="button" class="chat-inline-code copy-id" title="Copy code" data-chat-copy="inline-code">'+content+'</button>';result+=CHAT_INLINE_CODE_PREFIX+(inline.push(button)-1)+CHAT_INLINE_CODE_SUFFIX;index=end+tickCount}return result}
function formatChatBold(text){return text.replace(/(?<!\*)\*\*(?!\s)([^\n]*?\S)\*\*(?!\*)/g,'<strong>$1</strong>')}
