function formatChatLinks(text){return text.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g,(_match,label,url)=>{const safeUrl=sanitizeChatUrl(String(url).replace(/&amp;/g,'&'));return '<a class="chat-link" href="'+attr(safeUrl)+'" target="_blank" rel="noreferrer noopener">'+label+'</a>'})}
