function formatChatBlockquotes(text){const lines=text.split('\n');const out=[];let quote=[];const flush=()=>{if(quote.length){out.push('<blockquote class="chat-blockquote">'+quote.join('\n')+'</blockquote>');quote=[]}};for(const line of lines){const match=line.match(/^&gt; ?(.*)$/);if(match){quote.push(match[1]);continue}flush();out.push(line)}flush();return out.join('\n')}
function formatChatLists(text){const lines=text.split('\n');const out=[];let list=null;let itemOpen=false;const closeItem=()=>{if(itemOpen){out.push('</li>');itemOpen=false}};const flush=()=>{closeItem();if(list){out.push('</'+list+'>');list=null}};const openList=(type,className,start='')=>{if(list!==type){flush();out.push('<'+type+' class="'+className+'"'+(start?' start="'+start+'"':'')+'>');list=type}};const startItem=content=>{closeItem();out.push('<li>'+content);itemOpen=true};for(const line of lines){const task=line.match(/^\s*[-*]\s+\[([ xX])\]\s+(.+)$/);const bullet=line.match(/^\s*[-*]\s+(.+)$/);const ordered=line.match(/^\s*(\d+)[.)]\s+(.+)$/);if(task){openList('ul','chat-list chat-task-list');const checked=task[1].toLowerCase()==='x'?'[x]':'[ ]';startItem('<span class="chat-task-mark">'+checked+'</span> '+task[2]);continue}if(bullet){openList('ul','chat-list');startItem(bullet[1]);continue}if(ordered){openList('ol','chat-list',ordered[1]);startItem(ordered[2]);continue}if(list&&itemOpen&&line.trim()){out.push('<span class="chat-list-continuation">'+line.trim()+'</span>');continue}flush();out.push(line)}flush();return normalizeChatListSpacing(out.join('\n'))}
