function playCompletionSound(){if(!state.completionSound)return;const start=ctx=>{const now=ctx.currentTime;const output=ctx.createGain();output.gain.setValueAtTime(0.0001,now);output.gain.exponentialRampToValueAtTime(0.42,now+0.006);output.gain.exponentialRampToValueAtTime(0.0001,now+0.18);output.connect(ctx.destination);const beep=ctx.createOscillator();beep.type='square';beep.frequency.setValueAtTime(880,now);beep.frequency.setValueAtTime(880,now+0.11);beep.connect(output);beep.start(now);beep.stop(now+0.19);const tone=ctx.createOscillator();tone.type='sine';tone.frequency.setValueAtTime(1320,now+0.012);tone.connect(output);tone.start(now+0.012);tone.stop(now+0.13)};try{const ctx=completionAudioContext();if(!ctx)return;if(ctx.state==='suspended')void ctx.resume().then(()=>start(ctx)).catch(()=>{});else start(ctx)}catch{}}
